CREATE TABLE IF NOT EXISTS workspaces(id text PRIMARY KEY, name text NOT NULL, settings jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS owners(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), email text NOT NULL UNIQUE, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agents(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), role_key text NOT NULL, data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,role_key), UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS instruction_versions(id text PRIMARY KEY, workspace_id text NOT NULL, agent_id text NOT NULL, version integer NOT NULL, text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), UNIQUE(agent_id,version));
CREATE TABLE IF NOT EXISTS projects(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS memories(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), agent_id text, project_id text, scope text NOT NULL CHECK(scope IN ('workspace','project','agent')), data jsonb NOT NULL, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE IF NOT EXISTS tasks(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), agent_id text NOT NULL, status text NOT NULL, data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, claimed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS task_runs(id text PRIMARY KEY, workspace_id text NOT NULL, task_id text NOT NULL, runtime_id text UNIQUE, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS task_steps(id text PRIMARY KEY, workspace_id text NOT NULL, task_id text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS messages(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), agent_id text NOT NULL, task_id text, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS approvals(id text PRIMARY KEY, workspace_id text NOT NULL, task_id text NOT NULL, agent_id text NOT NULL, state text NOT NULL DEFAULT 'pending', params jsonb NOT NULL, task_version integer NOT NULL, version integer NOT NULL DEFAULT 1, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id));
CREATE TABLE IF NOT EXISTS artifacts(id text PRIMARY KEY, workspace_id text NOT NULL, task_id text NOT NULL, agent_id text NOT NULL, version integer NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), UNIQUE(task_id,version));
CREATE TABLE IF NOT EXISTS attachments(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), task_id text, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS usage_entries(id text PRIMARY KEY, workspace_id text NOT NULL, task_id text NOT NULL, agent_id text NOT NULL, state text NOT NULL, reserved_tokens integer NOT NULL CHECK(reserved_tokens>=0), input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, cost_microusd bigint, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id));
CREATE TABLE IF NOT EXISTS notifications(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), task_id text, kind text NOT NULL, data jsonb NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS audit_events(id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), task_id text, type text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS command_requests(workspace_id text NOT NULL REFERENCES workspaces(id), request_id text NOT NULL, type text NOT NULL, fingerprint text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,request_id));
CREATE INDEX IF NOT EXISTS tasks_workspace_status ON tasks(workspace_id,status);
CREATE INDEX IF NOT EXISTS audit_workspace_time ON audit_events(workspace_id,created_at);
